//! session `last_error` 命名空間（arch §3.2；與 `ErrorCode` 互不轉換）。
//!
//! 具名值依 YAML `values` 順序生成為 unit variant；動態前綴（`NAME:*`）生成為帶原因字串的 tuple variant。

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum SessionLastError {
    /// attach 過程中 bridge 啟動或 probe 拋出例外，session 回到 DETACHED；實際值為 ATTACH_FAILED:\<例外類別名>
    AttachFailed(String),
    /// platform 為 bcm 時等待 BCM CLI 提示（>）逾時
    BcmPromptTimeout,
    /// ATTACHED 狀態下自動重探命中 U-Boot 或 bootloader 提示且重探已耗盡；session 停在 ATTACHED，不再自動重探
    BootloaderStuck,
    /// UART 讀取或 select 失敗，bridge 已斷，session 轉為 DETACHED；實際值為 BRIDGE_DOWN:\<reason>
    BridgeDown(String),
    /// operator 執行 session clear 後，session 解除綁定並以此值記錄
    Cleared,
    /// console_unlock 步驟遇到 CFE 或 bootloader 提示，不送 secret 並停止後續 TX；空行 probe 之前判定者為零 TX，之後判定者該處之前已送出一次空行 probe
    ConsoleUnlockBootloader,
    /// console_unlock 等待 RX 閒置逾時（console 持續有輸出，未能靜默）；從未送出 secret。空行 probe 之前判定者為零 TX，之後判定者該處之前已送出一次空行 probe（已有 TX，仍未送 secret）
    ConsoleUnlockIdleTimeout,
    /// 送出 console_unlock secret 後等不到 prompt（逾時）
    ConsoleUnlockPromptTimeout,
    /// profile 宣告了帳密來源（user_env、pass_env 或 env_file）但解析為空（env_file 缺失、不可讀或缺 key）；屬登入終態，daemon 不對 login prompt 送空帳密，也不自動重探
    CredentialsUnresolved,
    /// bind 或 attach 時 device_by_id 不在目前裝置清單中
    DeviceNotFound,
    /// 同一 device_by_id 的裝置 real_path 改變（rebound），session 轉為 DETACHED
    DeviceReboundRequired,
    /// 裝置自 /dev 消失，session 轉為 DETACHED
    DeviceRemoved,
    /// attach 收尾時發現裝置已移除（passthrough 不做 probe，收尾才檢查裝置是否仍在）
    DeviceRemovedDuringAttach,
    /// 等待 login 提示逾時（未見 login 提示）
    LoginPromptTimeout,
    /// rx tail 命中 login 或 password 提示，但目前流程不自動登入（#174 分流），需要人類 console 介入
    LoginRequired,
    /// login 提示出現，但未設定帳號（pass_env 有值以進入登入流程）
    LoginUserRequired,
    /// login 提示需要密碼，但 pass_env 指向的環境變數為空
    PassEnvMissing,
    /// profile 設定了 user_env 但缺 pass_env，login 與 password 提示皆出現
    PassEnvRequired,
    /// 登入成功後執行 post_login_cmd 逾時
    PostLoginCmdTimeout,
    /// 命令送出後等不到 prompt，且 CTRL_C／CTRL_D 皆未恢復（或 boot quiet 期間跳過強制按鍵）時，由 _transition_to_attached 轉為 ATTACHED
    PromptTimeout,
    /// attach 後 prompt 不可用（開機窗或 probe 未見 prompt）
    PromptUnavailable,
    /// platform 為 prpl（其餘未指定者一律歸此）時等待 prompt 逾時
    PrplPromptTimeout,
    /// READY 確認 nonce 逾時（ready_probe 的回聲未出現）
    ReadyNonceTimeout,
    /// ready_probe 之後等不到 prompt（逾時）
    ReadyPromptTimeout,
    /// human 來源的 reboot 命令已送出，session 停留於 ATTACHED，等待 target 重新開機
    Rebooting,
    /// session.bind 將 session 改綁到不同 device_by_id，session 轉為 DETACHED
    Rebound,
    /// reboot 恢復迴圈中 ensure_ready 拋出例外；worker 不結束，記錄此值並續迴圈
    RecoveryError,
    /// reboot 恢復逾時收尾；bridge 不存在時轉為 DETACHED，bridge 存在時保留既有的 last_error，無既有值則以此值收尾
    RecoveryTimeout,
    /// session 經 device release 讓出 UART（燒錄或裝置交接），僅操作者可重新附掛；daemon 重啟後由 state.json 還原為 RELEASED，但 last_error 不寫入 state.json，重啟後為 null
    Released,
    /// 自動重探的 probe 拋出例外；session 保持 ATTACHED，且此類錯誤不具自動重探資格。實際值為 REPROBE_FAILED:\<例外類別名>
    ReprobeFailed(String),
    /// console 輸出洪水淹沒 probe（rx_bytes_last_10s 超過閾值）；不是 console 死亡
    RxFlood,
    /// platform 為 shell 時等待 shell 提示（#）逾時
    ShellPromptTimeout,
    /// probe 全程零 RX 且 RX 凍結 30 秒以上，疑似 USB 或 usbip read-endpoint stall；serialwrap 的 recover 與 release+attach 無法自復
    TransportStall,
    /// user_env 指定的帳號環境變數缺漏
    /// （reachable:false）
    UserEnvMissing,
}

